<script setup lang="ts">
import {Play,Pause,Square,RotateCcw} from '@lucide/vue';import ViewModeControl from './ViewModeControl.vue';import ExplodedControl from './ExplodedControl.vue';import type {ViewMode} from '../data/turbine';
defineProps<{mode:ViewMode;level:number;paused:boolean;running:boolean;speed:number;ready:boolean}>();
const emit=defineEmits<{mode:[v:ViewMode];level:[v:number];pause:[];rotor:[];stop:[];speed:[v:number];reset:[]}>();
</script>
<template><footer class="toolbar"><fieldset :disabled="!ready"><ViewModeControl :mode="mode" @change="emit('mode',$event)"/><span class="toolbar-divider"/><ExplodedControl :level="level" :paused="paused" @change="emit('level',$event)" @pause="emit('pause')" @reset="emit('level',0)"/><span class="toolbar-divider"/><div class="rotor-control"><span class="control-label">叶轮演示 <small>SIMULATION</small></span><div class="rotor-buttons"><button class="icon-button" :class="{active:running}" :disabled="level>0" :aria-label="running?'暂停叶轮':'启动叶轮'" @click="emit('rotor')"><Pause v-if="running" :size="15"/><Play v-else :size="15"/></button><button class="icon-button" aria-label="停止叶轮" @click="emit('stop')"><Square :size="13"/></button><select :value="speed" aria-label="叶轮速度" @change="emit('speed',Number(($event.target as HTMLSelectElement).value))"><option v-for="s in [.25,.5,1,2]" :key="s" :value="s">{{s}}×</option></select></div></div><button class="reset-button" @click="emit('reset')"><RotateCcw :size="16"/><span>恢复整机<small>RESET ALL</small></span></button></fieldset></footer></template>
